1	package events
2	
3	import (
4		"errors"
5		"sort"
6		"strings"
7		"sync"
8		"time"
9	)
10	
11	// Event is a normalized operational signal recorded on the incident
12	// timeline. Labels carries optional trimmed metadata (environment, region,
13	// release version, ...); it is nil when the event has none.
14	type Event struct {
15		ID       string
16		Service  string
17		Severity string
18		Message  string
19		At       time.Time
20		Labels   map[string]string
21	}
22	
23	// Query selects events by optional service, severity, and label filters.
24	// Since and Until are pointers so an unset bound (nil, meaning unbounded in
25	// that direction) is distinguishable from an explicit boundary at the zero
26	// instant. Both bounds are inclusive.
27	type Query struct {
28		Service  string
29		Severity string
30		Since    *time.Time
31		Until    *time.Time
32		Labels   map[string]string
33	}
34	
35	// ValidationError reports that an event failed normalization.
36	type ValidationError struct{ Reason string }
37	
38	func (e *ValidationError) Error() string { return e.Reason }
39	
40	// IsValidationError reports whether err is an event validation failure.
41	func IsValidationError(err error) bool {
42		var target *ValidationError
