1	package httpapi
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"net/http/httptest"
9		"strings"
10		"sync"
11		"testing"
12	
13		"github.com/cocosolocoder/signalroom/internal/events"
14	)
15	
16	type fakeStorage struct {
17		mu       sync.Mutex
18		failNext bool
19		poisoned bool
20		appended []int
21	
22		// stall, when non-nil, blocks one Append (with the timeline write lock
23		// held) until the channel is closed; stallEntered is closed once that
24		// Append reaches the wait. armStall sets both up.
25		stall        chan struct{}
26		stallEntered chan struct{}
27	
28		cursorKey []byte
29		snapshots map[string][]byte
30	}
31	
32	// armStall makes the next Append block until the returned release channel is
33	// closed. The returned entered channel closes once that Append is waiting, so
34	// a test knows the batch is held mid commit.
35	func (f *fakeStorage) armStall() (release, entered chan struct{}) {
36		release = make(chan struct{})
37		entered = make(chan struct{})
38		f.mu.Lock()
39		f.stall = release
40		f.stallEntered = entered
41		f.mu.Unlock()
42		return release, entered
43	}
44	
45	func (f *fakeStorage) Append(batch []events.Event) error {
46		f.mu.Lock()
47		stall := f.stall
48		entered := f.stallEntered
49		f.stall = nil
50		f.stallEntered = nil
51		f.mu.Unlock()
52		if stall != nil {
53			// Only the first Append blocks: the stalled submission still holds
54			// the timeline lock, so no other Append can reach here concurrently.
55			close(entered)
56			<-stall
57		}
58		f.mu.Lock()
59		defer f.mu.Unlock()
60		if f.poisoned {
61			return errors.New("poisoned")
62		}
63		if f.failNext {
64			f.poisoned = true
65			f.failNext = false
66			return errors.New("simulated write failure")
67		}
68		f.appended = append(f.appended, len(batch))
69		return nil
70	}
71	
72	func (f *fakeStorage) Poisoned() bool {
73		f.mu.Lock()
74		defer f.mu.Unlock()
75		return f.poisoned
76	}
77	
78	func (f *fakeStorage) CursorKey() []byte {
79		f.mu.Lock()
80		defer f.mu.Unlock()
81		return f.cursorKey
82	}
83	
84	func (f *fakeStorage) SaveSnapshot(id string, payload []byte) error {
85		f.mu.Lock()
86		defer f.mu.Unlock()
87		if f.snapshots == nil {
88			f.snapshots = make(map[string][]byte)
89		}
90		f.snapshots[id] = append([]byte(nil), payload...)
91		return nil
92	}
93	
94	func (f *fakeStorage) LoadSnapshot(id string) ([]byte, error) {
95		f.mu.Lock()
96		defer f.mu.Unlock()
97		payload, ok := f.snapshots[id]
98		if !ok {
99			return nil, errors.New("snapshot not found")
100		}
101		return append([]byte(nil), payload...), nil
102	}
103	
104	func newTestServer(t *testing.T) (*httptest.Server, *fakeStorage, *events.Timeline) {
105		t.Helper()
106		tl := events.NewTimeline()
107		store := &fakeStorage{cursorKey: []byte("test-cursor-key-0123456789ab")}
108		server := httptest.NewServer(NewHandler(tl, store, store))
109		t.Cleanup(server.Close)
110		return server, store, tl
111	}
112	
113	func post(t *testing.T, server *httptest.Server, body string) (int, map[string]any) {
114		t.Helper()
115		resp, err := http.Post(server.URL+"/events", "application/json", strings.NewReader(body))
116		if err != nil {
117			t.Fatalf("post: %v", err)
118		}
119		defer resp.Body.Close()
120		return decode(t, resp)
121	}
122	
123	func decode(t *testing.T, resp *http.Response) (int, map[string]any) {
124		t.Helper()
125		raw, err := io.ReadAll(resp.Body)
126		if err != nil {
127			t.Fatalf("read body: %v", err)
128		}
129		var out map[string]any
130		if err := json.Unmarshal(raw, &out); err != nil {
131			t.Fatalf("decode %q: %v", raw, err)
132		}
133		return resp.StatusCode, out
134	}
135	
136	func get(t *testing.T, server *httptest.Server, query string) (int, any) {
137		t.Helper()
138		resp, err := http.Get(server.URL + "/events" + query)
139		if err != nil {
140			t.Fatalf("get: %v", err)
141		}
142		defer resp.Body.Close()
143		raw, err := io.ReadAll(resp.Body)
144		if err != nil {
145			t.Fatalf("read: %v", err)
146		}
147		var anyBody any
148		if err := json.Unmarshal(raw, &anyBody); err != nil {
149			t.Fatalf("decode %q: %v", raw, err)
150		}
151		return resp.StatusCode, anyBody
152	}
153	
154	func TestPostCreatesReplaysAndPersists(t *testing.T) {
155		server, store, _ := newTestServer(t)
156		body := `{"events":[
157			{"id":"e1","service":"gateway","severity":" CRITICAL ","message":" spike ","at":"2026-10-01T10:00:00.123456789+08:00"},
158			{"id":"e2","service":"api","severity":"info","message":"ok","at":"2026-10-01T09:00:00Z"}
159		]}`
160		status, out := post(t, server, body)
161		if status != http.StatusOK {
162			t.Fatalf("status=%d body=%v", status, out)
163		}
